"use strict";(self.webpackChunkvenus_design_system=self.webpackChunkvenus_design_system||[]).push([[9619],{"./projects/plutao-ds/src/lib/foundations/typography/typography.stories.ts"(__unused_webpack_module,__webpack_exports__,__webpack_require__){__webpack_require__.r(__webpack_exports__);const CODIGO_INLINE="\n  background: var(--color-theme-upper);\n  border: 1px solid var(--color-stroke-frame);\n  border-radius: var(--size-radius-4, 4px);\n  padding: 1px 6px;\n  font-size: 12px;\n  font-family: 'Source Code Pro', monospace;\n  color: var(--color-text-essential-body);\n".trim(),LABEL_HEADER="\n  font-size: 11px;\n  font-weight: 600;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  color: var(--color-text-essential-caption);\n".trim(),BADGE_DEFINIR="\n  display: inline-block;\n  font-size: 10px;\n  font-weight: 600;\n  padding: 1px 6px;\n  border-radius: var(--size-radius-4, 4px);\n  background: var(--color-state-feedback-warning-surface-base);\n  color: var(--color-text-static-white);\n  letter-spacing: 0.04em;\n  vertical-align: middle;\n".trim(),BADGE_NAO_DISPONIVEL="\n  display: inline-block;\n  font-size: 10px;\n  font-weight: 600;\n  padding: 1px 6px;\n  border-radius: var(--size-radius-4, 4px);\n  background: var(--color-state-feedback-negative-surface-base);\n  color: var(--color-text-static-white);\n  letter-spacing: 0.04em;\n  vertical-align: middle;\n".trim(),__WEBPACK_DEFAULT_EXPORT__={title:"Fundamentos/Typography",tags:["autodocs"],parameters:{layout:"padded",controls:{disable:!0},actions:{disable:!0},docs:{description:{component:"Os tokens de tipografia do Venus.ds definem as escalas compostas que garantem hierarquia, legibilidade e consistência visual em toda a interface. Aplique-os via classe CSS (ex.: `lui-text-body`) ou diretamente pelo token CSS (ex.: `--size-font-body-16`). Ambos são acessíveis via SCSS no pacote de tokens do Venus.ds."}}}},Documentacao={name:"Documentação",parameters:{controls:{disable:!0},actions:{disable:!0}},render:()=>({template:`\n      <div class="typo-page" style="\n        max-width: 860px;\n        font-family: var(--font-family-primary, 'DM Sans', sans-serif);\n        color: var(--color-text-essential-body);\n        font-size: 14px;\n        line-height: 1.6;\n      ">\n\n        \x3c!-- ══ SEÇÃO TYPOGRAPHY ══════════════════════════════════════════ --\x3e\n        <section style="margin-bottom: 48px;">\n          <h1 style="\n            font-size: clamp(20px, 2.5vw, 24px);\n            font-weight: 700;\n            color: var(--color-text-essential-heading);\n            margin: 0 0 16px;\n          ">Typography</h1>\n\n          <p style="margin: 0 0 12px;">\n            Os tokens de tipografia do Venus.ds definem as <strong>escalas compostas</strong>\n            que garantem hierarquia, legibilidade e consistência visual em toda a interface.\n          </p>\n          <p style="margin: 0;">\n            Aplique-os via classe CSS (ex.:\n            <code style="${CODIGO_INLINE}">lui-text-body</code>)\n            ou diretamente pelo token CSS (ex.:\n            <code style="${CODIGO_INLINE}">--size-font-body-16</code>).\n            Ambos são acessíveis via SCSS no pacote de tokens do Venus.ds.\n          </p>\n        </section>\n\n        \x3c!-- ══ ESCALAS COMPOSTAS ════════════════════════════════════════ --\x3e\n        <section style="margin-bottom: 56px;">\n          <h2 style="\n            font-size: clamp(16px, 2vw, 18px);\n            font-weight: 700;\n            color: var(--color-text-essential-heading);\n            margin: 0 0 8px;\n          ">Escalas Compostas</h2>\n          <p style="margin: 0 0 24px; color: var(--color-text-essential-caption); font-size: 13px;">\n            Cada estilo composto agrupa tamanho, peso, altura de linha e família.\n            Aplique a classe CSS correspondente ou o token CSS diretamente.\n          </p>\n\n          \x3c!-- Cabeçalho --\x3e\n          <div class="typo-scale-header" style="\n            display: grid;\n            grid-template-columns: 120px 220px 1fr 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 0 16px 8px;\n            border-bottom: 2px solid var(--color-stroke-frame);\n            margin-bottom: 4px;\n          ">\n            <span style="${LABEL_HEADER}">Estilo</span>\n            <span style="${LABEL_HEADER}">Classe / Token</span>\n            <span style="${LABEL_HEADER}">Preview</span>\n            <span style="${LABEL_HEADER}">Uso recomendado</span>\n          </div>\n\n          \x3c!-- Display ────────────────────────────────────────────────── --\x3e\n          <div class="typo-scale-row" style="\n            display: grid;\n            grid-template-columns: 120px 220px 1fr 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 16px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              Display\n            </span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              .lui-text-display\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <br>\n              <code style="${CODIGO_INLINE}">--size-font-heading-40</code>\n            </span>\n            <span style="\n              font-size: var(--size-font-heading-40, 40px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n              line-height: 1.2;\n              overflow: hidden;\n              text-overflow: ellipsis;\n              white-space: nowrap;\n            ">O design system cuida dos detalhes.</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">\n              Títulos de destaque, hero sections\n            </span>\n          </div>\n\n          \x3c!-- Heading H1 ────────────────────────────────────────────── --\x3e\n          <div class="typo-scale-row" style="\n            display: grid;\n            grid-template-columns: 120px 220px 1fr 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              Heading H1\n            </span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              .lui-text-h1\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <br>\n              <code style="${CODIGO_INLINE}">--size-font-heading-32</code>\n            </span>\n            <span style="\n              font-size: var(--size-font-heading-32, 32px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n              line-height: 1.2;\n            ">O design system cuida dos detalhes.</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">\n              Títulos de página\n            </span>\n          </div>\n\n          \x3c!-- Heading H2 ────────────────────────────────────────────── --\x3e\n          <div class="typo-scale-row" style="\n            display: grid;\n            grid-template-columns: 120px 220px 1fr 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              Heading H2\n            </span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              .lui-text-h2\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <br>\n              <code style="${CODIGO_INLINE}">--size-font-heading-24</code>\n            </span>\n            <span style="\n              font-size: var(--size-font-heading-24, 24px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n              line-height: 1.3;\n            ">O design system cuida dos detalhes.</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">\n              Títulos de seção\n            </span>\n          </div>\n\n          \x3c!-- Heading H3 ────────────────────────────────────────────── --\x3e\n          <div class="typo-scale-row" style="\n            display: grid;\n            grid-template-columns: 120px 220px 1fr 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              Heading H3\n            </span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              .lui-text-h3\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <br>\n              <code style="${CODIGO_INLINE}">--size-font-heading-20</code>\n            </span>\n            <span style="\n              font-size: var(--size-font-heading-20, 20px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n              line-height: 1.4;\n            ">O design system cuida dos detalhes.</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">\n              Sub-títulos, cards de destaque\n            </span>\n          </div>\n\n          \x3c!-- Body-lg ────────────────────────────────────────────────── --\x3e\n          <div class="typo-scale-row" style="\n            display: grid;\n            grid-template-columns: 120px 220px 1fr 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              Body-lg\n            </span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              .lui-text-body-lg\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <br>\n              <code style="${CODIGO_INLINE}">--size-font-body-16</code>\n            </span>\n            <span style="\n              font-size: var(--size-font-body-16, 16px);\n              font-weight: 500;\n              color: var(--color-text-essential-body);\n              line-height: 1.5;\n            ">O design system cuida dos detalhes.</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">\n              Corpo de texto em destaque\n            </span>\n          </div>\n\n          \x3c!-- Body ───────────────────────────────────────────────────── --\x3e\n          <div class="typo-scale-row" style="\n            display: grid;\n            grid-template-columns: 120px 220px 1fr 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              Body\n            </span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              .lui-text-body\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <br>\n              <code style="${CODIGO_INLINE}">--size-font-body-14</code>\n            </span>\n            <span style="\n              font-size: var(--size-font-body-14, 14px);\n              font-weight: 400;\n              color: var(--color-text-essential-body);\n              line-height: 1.5;\n            ">O design system cuida dos detalhes.</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">\n              Texto corrido, descrições\n            </span>\n          </div>\n\n          \x3c!-- Caption ────────────────────────────────────────────────── --\x3e\n          <div class="typo-scale-row" style="\n            display: grid;\n            grid-template-columns: 120px 220px 1fr 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              Caption\n            </span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              .lui-text-caption\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <br>\n              <code style="${CODIGO_INLINE}">--size-font-body-12</code>\n            </span>\n            <span style="\n              font-size: var(--size-font-body-12, 12px);\n              font-weight: 400;\n              color: var(--color-text-essential-caption);\n              line-height: 1.5;\n            ">O design system cuida dos detalhes.</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">\n              Labels, legendas, metadados\n            </span>\n          </div>\n        </section>\n\n        \x3c!-- ══ TAMANHOS DE FONTE ════════════════════════════════════════ --\x3e\n        <section style="margin-bottom: 56px;">\n          <h2 style="\n            font-size: clamp(16px, 2vw, 18px);\n            font-weight: 700;\n            color: var(--color-text-essential-heading);\n            margin: 0 0 8px;\n          ">Tamanhos de Fonte</h2>\n          <p style="margin: 0 0 24px; color: var(--color-text-essential-caption); font-size: 13px;">\n            Escala de tamanhos disponíveis para body e heading.\n            Use o token CSS diretamente na propriedade\n            <code style="${CODIGO_INLINE}">font-size</code>.\n          </p>\n\n          \x3c!-- Cabeçalho --\x3e\n          <div class="typo-size-header" style="\n            display: grid;\n            grid-template-columns: 80px 1fr 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 0 16px 8px;\n            border-bottom: 2px solid var(--color-stroke-frame);\n            margin-bottom: 4px;\n          ">\n            <span style="${LABEL_HEADER}">Preview</span>\n            <span style="${LABEL_HEADER}">Token CSS</span>\n            <span style="${LABEL_HEADER}">Valor</span>\n            <span style="${LABEL_HEADER}">Uso recomendado</span>\n          </div>\n\n          \x3c!-- heading-40 ─────────────────────────────────────────────── --\x3e\n          <div class="typo-size-row" style="\n            display: grid;\n            grid-template-columns: 80px 1fr 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 10px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="\n              font-size: var(--size-font-heading-40, 40px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n              line-height: 1;\n            ">Aa</span>\n            <code style="${CODIGO_INLINE}">--size-font-heading-40</code>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">40px</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Display</span>\n          </div>\n\n          \x3c!-- heading-32 ─────────────────────────────────────────────── --\x3e\n          <div class="typo-size-row" style="\n            display: grid;\n            grid-template-columns: 80px 1fr 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 10px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="\n              font-size: var(--size-font-heading-32, 32px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n              line-height: 1;\n            ">Aa</span>\n            <code style="${CODIGO_INLINE}">--size-font-heading-32</code>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">32px</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Heading H1</span>\n          </div>\n\n          \x3c!-- heading-24 ─────────────────────────────────────────────── --\x3e\n          <div class="typo-size-row" style="\n            display: grid;\n            grid-template-columns: 80px 1fr 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 10px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="\n              font-size: var(--size-font-heading-24, 24px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n              line-height: 1;\n            ">Aa</span>\n            <code style="${CODIGO_INLINE}">--size-font-heading-24</code>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">24px</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Heading H2</span>\n          </div>\n\n          \x3c!-- heading-20 ─────────────────────────────────────────────── --\x3e\n          <div class="typo-size-row" style="\n            display: grid;\n            grid-template-columns: 80px 1fr 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 10px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="\n              font-size: var(--size-font-heading-20, 20px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n              line-height: 1;\n            ">Aa</span>\n            <code style="${CODIGO_INLINE}">--size-font-heading-20</code>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">20px</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Heading H3</span>\n          </div>\n\n          \x3c!-- body-16 ────────────────────────────────────────────────── --\x3e\n          <div class="typo-size-row" style="\n            display: grid;\n            grid-template-columns: 80px 1fr 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 10px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="\n              font-size: var(--size-font-body-16, 16px);\n              font-weight: 400;\n              color: var(--color-text-essential-heading);\n              line-height: 1;\n            ">Aa</span>\n            <code style="${CODIGO_INLINE}">--size-font-body-16</code>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">16px</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Body padrão</span>\n          </div>\n\n          \x3c!-- body-14 ────────────────────────────────────────────────── --\x3e\n          <div class="typo-size-row" style="\n            display: grid;\n            grid-template-columns: 80px 1fr 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 10px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="\n              font-size: var(--size-font-body-14, 14px);\n              font-weight: 400;\n              color: var(--color-text-essential-heading);\n              line-height: 1;\n            ">Aa</span>\n            <code style="${CODIGO_INLINE}">--size-font-body-14</code>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">14px</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Body pequeno</span>\n          </div>\n\n          \x3c!-- body-12 ────────────────────────────────────────────────── --\x3e\n          <div class="typo-size-row" style="\n            display: grid;\n            grid-template-columns: 80px 1fr 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 10px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="\n              font-size: var(--size-font-body-12, 12px);\n              font-weight: 400;\n              color: var(--color-text-essential-heading);\n              line-height: 1;\n            ">Aa</span>\n            <code style="${CODIGO_INLINE}">--size-font-body-12</code>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">12px</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Caption</span>\n          </div>\n        </section>\n\n        \x3c!-- ══ PESOS TIPOGRÁFICOS ═══════════════════════════════════════ --\x3e\n        <section style="margin-bottom: 56px;">\n          <h2 style="\n            font-size: clamp(16px, 2vw, 18px);\n            font-weight: 700;\n            color: var(--color-text-essential-heading);\n            margin: 0 0 8px;\n          ">Pesos Tipográficos</h2>\n          <p style="margin: 0 0 24px; color: var(--color-text-essential-caption); font-size: 13px;">\n            Pesos disponíveis na fonte DM Sans (carregada via Google Fonts).\n            Pesos não disponíveis são sinalizados.\n          </p>\n\n          \x3c!-- Cabeçalho --\x3e\n          <div class="typo-weight-header" style="\n            display: grid;\n            grid-template-columns: 120px 80px 1fr 200px;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 0 16px 8px;\n            border-bottom: 2px solid var(--color-stroke-frame);\n            margin-bottom: 4px;\n          ">\n            <span style="${LABEL_HEADER}">Peso</span>\n            <span style="${LABEL_HEADER}">Valor</span>\n            <span style="${LABEL_HEADER}">Preview</span>\n            <span style="${LABEL_HEADER}">Token / Status</span>\n          </div>\n\n          \x3c!-- Light 300 ─────────────────────────────────────────────── --\x3e\n          <div class="typo-weight-row" style="\n            display: grid;\n            grid-template-columns: 120px 80px 1fr 200px;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n            opacity: 0.5;\n          ">\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Light</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">300</span>\n            <span style="\n              font-size: var(--size-font-body-16, 16px);\n              font-weight: 300;\n              color: var(--color-text-essential-heading);\n            ">Typography</span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-weight-light\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <span style="${BADGE_NAO_DISPONIVEL}">não disponível</span>\n            </span>\n          </div>\n\n          \x3c!-- Regular 400 ────────────────────────────────────────────── --\x3e\n          <div class="typo-weight-row" style="\n            display: grid;\n            grid-template-columns: 120px 80px 1fr 200px;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Regular</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">400</span>\n            <span style="\n              font-size: var(--size-font-body-16, 16px);\n              font-weight: 400;\n              color: var(--color-text-essential-heading);\n            ">Typography</span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-weight-regular\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n          </div>\n\n          \x3c!-- Medium 500 ─────────────────────────────────────────────── --\x3e\n          <div class="typo-weight-row" style="\n            display: grid;\n            grid-template-columns: 120px 80px 1fr 200px;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Medium</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">500</span>\n            <span style="\n              font-size: var(--size-font-body-16, 16px);\n              font-weight: 500;\n              color: var(--color-text-essential-heading);\n            ">Typography</span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-weight-medium\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n          </div>\n\n          \x3c!-- Semibold 600 ────────────────────────────────────────────── --\x3e\n          <div class="typo-weight-row" style="\n            display: grid;\n            grid-template-columns: 120px 80px 1fr 200px;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n            opacity: 0.5;\n          ">\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Semibold</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">600</span>\n            <span style="\n              font-size: var(--size-font-body-16, 16px);\n              font-weight: 600;\n              color: var(--color-text-essential-heading);\n            ">Typography</span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-weight-semibold\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <span style="${BADGE_NAO_DISPONIVEL}">não disponível</span>\n            </span>\n          </div>\n\n          \x3c!-- Bold 700 ────────────────────────────────────────────────── --\x3e\n          <div class="typo-weight-row" style="\n            display: grid;\n            grid-template-columns: 120px 80px 1fr 200px;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Bold</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">700</span>\n            <span style="\n              font-size: var(--size-font-body-16, 16px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n            ">Typography</span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-weight-bold\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n          </div>\n        </section>\n\n        \x3c!-- ══ ALTURAS DE LINHA ══════════════════════════════════════════ --\x3e\n        <section style="margin-bottom: 56px;">\n          <h2 style="\n            font-size: clamp(16px, 2vw, 18px);\n            font-weight: 700;\n            color: var(--color-text-essential-heading);\n            margin: 0 0 8px;\n          ">Alturas de Linha</h2>\n          <p style="margin: 0 0 24px; color: var(--color-text-essential-caption); font-size: 13px;">\n            Escala de <code style="${CODIGO_INLINE}">line-height</code>\n            para controlar o espaçamento vertical entre linhas de texto.\n          </p>\n\n          \x3c!-- Cabeçalho --\x3e\n          <div class="typo-lh-header" style="\n            display: grid;\n            grid-template-columns: 220px 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 0 16px 8px;\n            border-bottom: 2px solid var(--color-stroke-frame);\n            margin-bottom: 4px;\n          ">\n            <span style="${LABEL_HEADER}">Token</span>\n            <span style="${LABEL_HEADER}">Valor</span>\n            <span style="${LABEL_HEADER}">Exemplo</span>\n          </div>\n\n          \x3c!-- line-height 1 ───────────────────────────────────────────── --\x3e\n          <div class="typo-lh-row" style="\n            display: grid;\n            grid-template-columns: 220px 80px 1fr;\n            gap: 8px 20px;\n            align-items: start;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-line-height-xs\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">1</span>\n            <p style="\n              margin: 0;\n              font-size: var(--size-font-body-14, 14px);\n              line-height: 1;\n              color: var(--color-text-essential-body);\n            ">Os tokens de tipografia garantem hierarquia visual e legibilidade consistente em toda a interface do Venus.ds.</p>\n          </div>\n\n          \x3c!-- line-height 1.1 ─────────────────────────────────────────── --\x3e\n          <div class="typo-lh-row" style="\n            display: grid;\n            grid-template-columns: 220px 80px 1fr;\n            gap: 8px 20px;\n            align-items: start;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-line-height-sm\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">1.1</span>\n            <p style="\n              margin: 0;\n              font-size: var(--size-font-body-14, 14px);\n              line-height: 1.1;\n              color: var(--color-text-essential-body);\n            ">Os tokens de tipografia garantem hierarquia visual e legibilidade consistente em toda a interface do Venus.ds.</p>\n          </div>\n\n          \x3c!-- line-height 1.25 ────────────────────────────────────────── --\x3e\n          <div class="typo-lh-row" style="\n            display: grid;\n            grid-template-columns: 220px 80px 1fr;\n            gap: 8px 20px;\n            align-items: start;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-line-height-md\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">1.25</span>\n            <p style="\n              margin: 0;\n              font-size: var(--size-font-body-14, 14px);\n              line-height: 1.25;\n              color: var(--color-text-essential-body);\n            ">Os tokens de tipografia garantem hierarquia visual e legibilidade consistente em toda a interface do Venus.ds.</p>\n          </div>\n\n          \x3c!-- line-height 1.5 ─────────────────────────────────────────── --\x3e\n          <div class="typo-lh-row" style="\n            display: grid;\n            grid-template-columns: 220px 80px 1fr;\n            gap: 8px 20px;\n            align-items: start;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-line-height-lg\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">1.5</span>\n            <p style="\n              margin: 0;\n              font-size: var(--size-font-body-14, 14px);\n              line-height: 1.5;\n              color: var(--color-text-essential-body);\n            ">Os tokens de tipografia garantem hierarquia visual e legibilidade consistente em toda a interface do Venus.ds.</p>\n          </div>\n\n          \x3c!-- line-height 1.7 ─────────────────────────────────────────── --\x3e\n          <div class="typo-lh-row" style="\n            display: grid;\n            grid-template-columns: 220px 80px 1fr;\n            gap: 8px 20px;\n            align-items: start;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-line-height-xl\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">1.7</span>\n            <p style="\n              margin: 0;\n              font-size: var(--size-font-body-14, 14px);\n              line-height: 1.7;\n              color: var(--color-text-essential-body);\n            ">Os tokens de tipografia garantem hierarquia visual e legibilidade consistente em toda a interface do Venus.ds.</p>\n          </div>\n\n          \x3c!-- line-height 2 ───────────────────────────────────────────── --\x3e\n          <div class="typo-lh-row" style="\n            display: grid;\n            grid-template-columns: 220px 80px 1fr;\n            gap: 8px 20px;\n            align-items: start;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-line-height-2xl\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">2</span>\n            <p style="\n              margin: 0;\n              font-size: var(--size-font-body-14, 14px);\n              line-height: 2;\n              color: var(--color-text-essential-body);\n            ">Os tokens de tipografia garantem hierarquia visual e legibilidade consistente em toda a interface do Venus.ds.</p>\n          </div>\n        </section>\n\n        \x3c!-- ══ FAMÍLIAS TIPOGRÁFICAS ════════════════════════════════════ --\x3e\n        <section style="margin-bottom: 56px;">\n          <h2 style="\n            font-size: clamp(16px, 2vw, 18px);\n            font-weight: 700;\n            color: var(--color-text-essential-heading);\n            margin: 0 0 8px;\n          ">Famílias Tipográficas</h2>\n          <p style="margin: 0 0 24px; color: var(--color-text-essential-caption); font-size: 13px;">\n            Famílias de fonte disponíveis no Venus.ds.\n          </p>\n\n          \x3c!-- Cabeçalho --\x3e\n          <div class="typo-family-header" style="\n            display: grid;\n            grid-template-columns: 160px 240px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 0 16px 8px;\n            border-bottom: 2px solid var(--color-stroke-frame);\n            margin-bottom: 4px;\n          ">\n            <span style="${LABEL_HEADER}">Família</span>\n            <span style="${LABEL_HEADER}">Token CSS</span>\n            <span style="${LABEL_HEADER}">Preview</span>\n          </div>\n\n          \x3c!-- DM Sans ────────────────────────────────────────────────── --\x3e\n          <div class="typo-family-row" style="\n            display: grid;\n            grid-template-columns: 160px 240px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 16px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              DM Sans\n            </span>\n            <code style="${CODIGO_INLINE}">--font-family-primary</code>\n            <span style="\n              font-family: var(--font-family-primary, 'DM Sans', sans-serif);\n              font-size: var(--size-font-heading-20, 20px);\n              color: var(--color-text-essential-heading);\n            ">ABCDEFGHIJ abcdefghij 0123456789</span>\n          </div>\n\n          \x3c!-- Source Code Pro ─────────────────────────────────────────── --\x3e\n          <div class="typo-family-row" style="\n            display: grid;\n            grid-template-columns: 160px 240px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 16px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              Source Code Pro\n            </span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-family-code\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n            <span style="\n              font-family: 'Source Code Pro', monospace;\n              font-size: var(--size-font-body-14, 14px);\n              color: var(--color-text-essential-heading);\n            ">ABCDEFGHIJ abcdefghij 0123456789</span>\n          </div>\n        </section>\n\n        \x3c!-- ══ NOTA SOBRE TOKENS A DEFINIR ════════════════════════════ --\x3e\n        <aside style="\n          margin-top: 48px;\n          padding: 16px 20px;\n          background: var(--color-theme-upper);\n          border-left: var(--size-stoke-2, 2px) solid var(--color-state-feedback-warning-surface-base);\n          border-radius: 0 var(--size-radius-4, 4px) var(--size-radius-4, 4px) 0;\n        ">\n          <p style="margin: 0 0 6px; font-weight: 600; color: var(--color-text-essential-heading);">\n            Tokens sinalizados como "a definir"\n          </p>\n          <p style="margin: 0; font-size: 13px; color: var(--color-text-essential-caption);">\n            Os tokens\n            <code style="${CODIGO_INLINE}">--lui-typography-*</code>,\n            <code style="${CODIGO_INLINE}">--tds-ref-font-weight-*</code>,\n            <code style="${CODIGO_INLINE}">--tds-ref-font-line-height-*</code> e\n            <code style="${CODIGO_INLINE}">--tds-ref-font-family-code</code>\n            ainda não foram definidos no pacote de tokens do Venus.ds.\n            Enquanto isso, utilize os tokens globais disponíveis\n            (<code style="${CODIGO_INLINE}">--size-font-*</code>,\n            <code style="${CODIGO_INLINE}">--font-family-primary</code>) e\n            alinhe com o time de tokens a criação dos aliases definitivos.\n            Os pesos sinalizados como "não disponível" correspondem a variações da DM Sans\n            não carregadas no Storybook (somente 400, 500 e 700 estão disponíveis).\n          </p>\n        </aside>\n\n      </div>\n    `,styles:["\n        @media (max-width: 1024px) {\n          .typo-page { max-width: 100% !important; }\n        }\n        @media (max-width: 640px) {\n          .typo-scale-header,\n          .typo-size-header,\n          .typo-weight-header,\n          .typo-lh-header,\n          .typo-family-header { display: none !important; }\n          .typo-scale-row {\n            grid-template-columns: 100px 1fr !important;\n            gap: 4px 12px !important;\n            padding: 10px 12px !important;\n          }\n          .typo-size-row {\n            grid-template-columns: 56px 1fr !important;\n            gap: 4px 12px !important;\n            padding: 10px 12px !important;\n          }\n          .typo-weight-row {\n            grid-template-columns: 80px 1fr !important;\n            gap: 4px 12px !important;\n            padding: 10px 12px !important;\n          }\n          .typo-lh-row {\n            grid-template-columns: 1fr !important;\n            gap: 4px !important;\n            padding: 10px 12px !important;\n          }\n          .typo-family-row {\n            grid-template-columns: 1fr !important;\n            gap: 4px !important;\n            padding: 10px 12px !important;\n          }\n        }\n      "]})};Documentacao.parameters={...Documentacao.parameters,docs:{...Documentacao.parameters?.docs,source:{originalSource:'{\n  name: \'Documentação\',\n  parameters: {\n    controls: {\n      disable: true\n    },\n    actions: {\n      disable: true\n    }\n  },\n  render: () => ({\n    template: `\n      <div class="typo-page" style="\n        max-width: 860px;\n        font-family: var(--font-family-primary, \'DM Sans\', sans-serif);\n        color: var(--color-text-essential-body);\n        font-size: 14px;\n        line-height: 1.6;\n      ">\n\n        \x3c!-- ══ SEÇÃO TYPOGRAPHY ══════════════════════════════════════════ --\x3e\n        <section style="margin-bottom: 48px;">\n          <h1 style="\n            font-size: clamp(20px, 2.5vw, 24px);\n            font-weight: 700;\n            color: var(--color-text-essential-heading);\n            margin: 0 0 16px;\n          ">Typography</h1>\n\n          <p style="margin: 0 0 12px;">\n            Os tokens de tipografia do Venus.ds definem as <strong>escalas compostas</strong>\n            que garantem hierarquia, legibilidade e consistência visual em toda a interface.\n          </p>\n          <p style="margin: 0;">\n            Aplique-os via classe CSS (ex.:\n            <code style="${CODIGO_INLINE}">lui-text-body</code>)\n            ou diretamente pelo token CSS (ex.:\n            <code style="${CODIGO_INLINE}">--size-font-body-16</code>).\n            Ambos são acessíveis via SCSS no pacote de tokens do Venus.ds.\n          </p>\n        </section>\n\n        \x3c!-- ══ ESCALAS COMPOSTAS ════════════════════════════════════════ --\x3e\n        <section style="margin-bottom: 56px;">\n          <h2 style="\n            font-size: clamp(16px, 2vw, 18px);\n            font-weight: 700;\n            color: var(--color-text-essential-heading);\n            margin: 0 0 8px;\n          ">Escalas Compostas</h2>\n          <p style="margin: 0 0 24px; color: var(--color-text-essential-caption); font-size: 13px;">\n            Cada estilo composto agrupa tamanho, peso, altura de linha e família.\n            Aplique a classe CSS correspondente ou o token CSS diretamente.\n          </p>\n\n          \x3c!-- Cabeçalho --\x3e\n          <div class="typo-scale-header" style="\n            display: grid;\n            grid-template-columns: 120px 220px 1fr 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 0 16px 8px;\n            border-bottom: 2px solid var(--color-stroke-frame);\n            margin-bottom: 4px;\n          ">\n            <span style="${LABEL_HEADER}">Estilo</span>\n            <span style="${LABEL_HEADER}">Classe / Token</span>\n            <span style="${LABEL_HEADER}">Preview</span>\n            <span style="${LABEL_HEADER}">Uso recomendado</span>\n          </div>\n\n          \x3c!-- Display ────────────────────────────────────────────────── --\x3e\n          <div class="typo-scale-row" style="\n            display: grid;\n            grid-template-columns: 120px 220px 1fr 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 16px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              Display\n            </span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              .lui-text-display\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <br>\n              <code style="${CODIGO_INLINE}">--size-font-heading-40</code>\n            </span>\n            <span style="\n              font-size: var(--size-font-heading-40, 40px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n              line-height: 1.2;\n              overflow: hidden;\n              text-overflow: ellipsis;\n              white-space: nowrap;\n            ">O design system cuida dos detalhes.</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">\n              Títulos de destaque, hero sections\n            </span>\n          </div>\n\n          \x3c!-- Heading H1 ────────────────────────────────────────────── --\x3e\n          <div class="typo-scale-row" style="\n            display: grid;\n            grid-template-columns: 120px 220px 1fr 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              Heading H1\n            </span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              .lui-text-h1\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <br>\n              <code style="${CODIGO_INLINE}">--size-font-heading-32</code>\n            </span>\n            <span style="\n              font-size: var(--size-font-heading-32, 32px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n              line-height: 1.2;\n            ">O design system cuida dos detalhes.</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">\n              Títulos de página\n            </span>\n          </div>\n\n          \x3c!-- Heading H2 ────────────────────────────────────────────── --\x3e\n          <div class="typo-scale-row" style="\n            display: grid;\n            grid-template-columns: 120px 220px 1fr 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              Heading H2\n            </span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              .lui-text-h2\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <br>\n              <code style="${CODIGO_INLINE}">--size-font-heading-24</code>\n            </span>\n            <span style="\n              font-size: var(--size-font-heading-24, 24px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n              line-height: 1.3;\n            ">O design system cuida dos detalhes.</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">\n              Títulos de seção\n            </span>\n          </div>\n\n          \x3c!-- Heading H3 ────────────────────────────────────────────── --\x3e\n          <div class="typo-scale-row" style="\n            display: grid;\n            grid-template-columns: 120px 220px 1fr 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              Heading H3\n            </span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              .lui-text-h3\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <br>\n              <code style="${CODIGO_INLINE}">--size-font-heading-20</code>\n            </span>\n            <span style="\n              font-size: var(--size-font-heading-20, 20px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n              line-height: 1.4;\n            ">O design system cuida dos detalhes.</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">\n              Sub-títulos, cards de destaque\n            </span>\n          </div>\n\n          \x3c!-- Body-lg ────────────────────────────────────────────────── --\x3e\n          <div class="typo-scale-row" style="\n            display: grid;\n            grid-template-columns: 120px 220px 1fr 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              Body-lg\n            </span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              .lui-text-body-lg\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <br>\n              <code style="${CODIGO_INLINE}">--size-font-body-16</code>\n            </span>\n            <span style="\n              font-size: var(--size-font-body-16, 16px);\n              font-weight: 500;\n              color: var(--color-text-essential-body);\n              line-height: 1.5;\n            ">O design system cuida dos detalhes.</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">\n              Corpo de texto em destaque\n            </span>\n          </div>\n\n          \x3c!-- Body ───────────────────────────────────────────────────── --\x3e\n          <div class="typo-scale-row" style="\n            display: grid;\n            grid-template-columns: 120px 220px 1fr 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              Body\n            </span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              .lui-text-body\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <br>\n              <code style="${CODIGO_INLINE}">--size-font-body-14</code>\n            </span>\n            <span style="\n              font-size: var(--size-font-body-14, 14px);\n              font-weight: 400;\n              color: var(--color-text-essential-body);\n              line-height: 1.5;\n            ">O design system cuida dos detalhes.</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">\n              Texto corrido, descrições\n            </span>\n          </div>\n\n          \x3c!-- Caption ────────────────────────────────────────────────── --\x3e\n          <div class="typo-scale-row" style="\n            display: grid;\n            grid-template-columns: 120px 220px 1fr 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              Caption\n            </span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              .lui-text-caption\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <br>\n              <code style="${CODIGO_INLINE}">--size-font-body-12</code>\n            </span>\n            <span style="\n              font-size: var(--size-font-body-12, 12px);\n              font-weight: 400;\n              color: var(--color-text-essential-caption);\n              line-height: 1.5;\n            ">O design system cuida dos detalhes.</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">\n              Labels, legendas, metadados\n            </span>\n          </div>\n        </section>\n\n        \x3c!-- ══ TAMANHOS DE FONTE ════════════════════════════════════════ --\x3e\n        <section style="margin-bottom: 56px;">\n          <h2 style="\n            font-size: clamp(16px, 2vw, 18px);\n            font-weight: 700;\n            color: var(--color-text-essential-heading);\n            margin: 0 0 8px;\n          ">Tamanhos de Fonte</h2>\n          <p style="margin: 0 0 24px; color: var(--color-text-essential-caption); font-size: 13px;">\n            Escala de tamanhos disponíveis para body e heading.\n            Use o token CSS diretamente na propriedade\n            <code style="${CODIGO_INLINE}">font-size</code>.\n          </p>\n\n          \x3c!-- Cabeçalho --\x3e\n          <div class="typo-size-header" style="\n            display: grid;\n            grid-template-columns: 80px 1fr 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 0 16px 8px;\n            border-bottom: 2px solid var(--color-stroke-frame);\n            margin-bottom: 4px;\n          ">\n            <span style="${LABEL_HEADER}">Preview</span>\n            <span style="${LABEL_HEADER}">Token CSS</span>\n            <span style="${LABEL_HEADER}">Valor</span>\n            <span style="${LABEL_HEADER}">Uso recomendado</span>\n          </div>\n\n          \x3c!-- heading-40 ─────────────────────────────────────────────── --\x3e\n          <div class="typo-size-row" style="\n            display: grid;\n            grid-template-columns: 80px 1fr 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 10px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="\n              font-size: var(--size-font-heading-40, 40px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n              line-height: 1;\n            ">Aa</span>\n            <code style="${CODIGO_INLINE}">--size-font-heading-40</code>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">40px</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Display</span>\n          </div>\n\n          \x3c!-- heading-32 ─────────────────────────────────────────────── --\x3e\n          <div class="typo-size-row" style="\n            display: grid;\n            grid-template-columns: 80px 1fr 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 10px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="\n              font-size: var(--size-font-heading-32, 32px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n              line-height: 1;\n            ">Aa</span>\n            <code style="${CODIGO_INLINE}">--size-font-heading-32</code>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">32px</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Heading H1</span>\n          </div>\n\n          \x3c!-- heading-24 ─────────────────────────────────────────────── --\x3e\n          <div class="typo-size-row" style="\n            display: grid;\n            grid-template-columns: 80px 1fr 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 10px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="\n              font-size: var(--size-font-heading-24, 24px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n              line-height: 1;\n            ">Aa</span>\n            <code style="${CODIGO_INLINE}">--size-font-heading-24</code>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">24px</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Heading H2</span>\n          </div>\n\n          \x3c!-- heading-20 ─────────────────────────────────────────────── --\x3e\n          <div class="typo-size-row" style="\n            display: grid;\n            grid-template-columns: 80px 1fr 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 10px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="\n              font-size: var(--size-font-heading-20, 20px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n              line-height: 1;\n            ">Aa</span>\n            <code style="${CODIGO_INLINE}">--size-font-heading-20</code>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">20px</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Heading H3</span>\n          </div>\n\n          \x3c!-- body-16 ────────────────────────────────────────────────── --\x3e\n          <div class="typo-size-row" style="\n            display: grid;\n            grid-template-columns: 80px 1fr 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 10px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="\n              font-size: var(--size-font-body-16, 16px);\n              font-weight: 400;\n              color: var(--color-text-essential-heading);\n              line-height: 1;\n            ">Aa</span>\n            <code style="${CODIGO_INLINE}">--size-font-body-16</code>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">16px</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Body padrão</span>\n          </div>\n\n          \x3c!-- body-14 ────────────────────────────────────────────────── --\x3e\n          <div class="typo-size-row" style="\n            display: grid;\n            grid-template-columns: 80px 1fr 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 10px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="\n              font-size: var(--size-font-body-14, 14px);\n              font-weight: 400;\n              color: var(--color-text-essential-heading);\n              line-height: 1;\n            ">Aa</span>\n            <code style="${CODIGO_INLINE}">--size-font-body-14</code>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">14px</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Body pequeno</span>\n          </div>\n\n          \x3c!-- body-12 ────────────────────────────────────────────────── --\x3e\n          <div class="typo-size-row" style="\n            display: grid;\n            grid-template-columns: 80px 1fr 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 10px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="\n              font-size: var(--size-font-body-12, 12px);\n              font-weight: 400;\n              color: var(--color-text-essential-heading);\n              line-height: 1;\n            ">Aa</span>\n            <code style="${CODIGO_INLINE}">--size-font-body-12</code>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">12px</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Caption</span>\n          </div>\n        </section>\n\n        \x3c!-- ══ PESOS TIPOGRÁFICOS ═══════════════════════════════════════ --\x3e\n        <section style="margin-bottom: 56px;">\n          <h2 style="\n            font-size: clamp(16px, 2vw, 18px);\n            font-weight: 700;\n            color: var(--color-text-essential-heading);\n            margin: 0 0 8px;\n          ">Pesos Tipográficos</h2>\n          <p style="margin: 0 0 24px; color: var(--color-text-essential-caption); font-size: 13px;">\n            Pesos disponíveis na fonte DM Sans (carregada via Google Fonts).\n            Pesos não disponíveis são sinalizados.\n          </p>\n\n          \x3c!-- Cabeçalho --\x3e\n          <div class="typo-weight-header" style="\n            display: grid;\n            grid-template-columns: 120px 80px 1fr 200px;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 0 16px 8px;\n            border-bottom: 2px solid var(--color-stroke-frame);\n            margin-bottom: 4px;\n          ">\n            <span style="${LABEL_HEADER}">Peso</span>\n            <span style="${LABEL_HEADER}">Valor</span>\n            <span style="${LABEL_HEADER}">Preview</span>\n            <span style="${LABEL_HEADER}">Token / Status</span>\n          </div>\n\n          \x3c!-- Light 300 ─────────────────────────────────────────────── --\x3e\n          <div class="typo-weight-row" style="\n            display: grid;\n            grid-template-columns: 120px 80px 1fr 200px;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n            opacity: 0.5;\n          ">\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Light</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">300</span>\n            <span style="\n              font-size: var(--size-font-body-16, 16px);\n              font-weight: 300;\n              color: var(--color-text-essential-heading);\n            ">Typography</span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-weight-light\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <span style="${BADGE_NAO_DISPONIVEL}">não disponível</span>\n            </span>\n          </div>\n\n          \x3c!-- Regular 400 ────────────────────────────────────────────── --\x3e\n          <div class="typo-weight-row" style="\n            display: grid;\n            grid-template-columns: 120px 80px 1fr 200px;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Regular</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">400</span>\n            <span style="\n              font-size: var(--size-font-body-16, 16px);\n              font-weight: 400;\n              color: var(--color-text-essential-heading);\n            ">Typography</span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-weight-regular\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n          </div>\n\n          \x3c!-- Medium 500 ─────────────────────────────────────────────── --\x3e\n          <div class="typo-weight-row" style="\n            display: grid;\n            grid-template-columns: 120px 80px 1fr 200px;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Medium</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">500</span>\n            <span style="\n              font-size: var(--size-font-body-16, 16px);\n              font-weight: 500;\n              color: var(--color-text-essential-heading);\n            ">Typography</span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-weight-medium\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n          </div>\n\n          \x3c!-- Semibold 600 ────────────────────────────────────────────── --\x3e\n          <div class="typo-weight-row" style="\n            display: grid;\n            grid-template-columns: 120px 80px 1fr 200px;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n            opacity: 0.5;\n          ">\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Semibold</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">600</span>\n            <span style="\n              font-size: var(--size-font-body-16, 16px);\n              font-weight: 600;\n              color: var(--color-text-essential-heading);\n            ">Typography</span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-weight-semibold\n              <span style="${BADGE_DEFINIR}">a definir</span>\n              <span style="${BADGE_NAO_DISPONIVEL}">não disponível</span>\n            </span>\n          </div>\n\n          \x3c!-- Bold 700 ────────────────────────────────────────────────── --\x3e\n          <div class="typo-weight-row" style="\n            display: grid;\n            grid-template-columns: 120px 80px 1fr 200px;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">Bold</span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">700</span>\n            <span style="\n              font-size: var(--size-font-body-16, 16px);\n              font-weight: 700;\n              color: var(--color-text-essential-heading);\n            ">Typography</span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-weight-bold\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n          </div>\n        </section>\n\n        \x3c!-- ══ ALTURAS DE LINHA ══════════════════════════════════════════ --\x3e\n        <section style="margin-bottom: 56px;">\n          <h2 style="\n            font-size: clamp(16px, 2vw, 18px);\n            font-weight: 700;\n            color: var(--color-text-essential-heading);\n            margin: 0 0 8px;\n          ">Alturas de Linha</h2>\n          <p style="margin: 0 0 24px; color: var(--color-text-essential-caption); font-size: 13px;">\n            Escala de <code style="${CODIGO_INLINE}">line-height</code>\n            para controlar o espaçamento vertical entre linhas de texto.\n          </p>\n\n          \x3c!-- Cabeçalho --\x3e\n          <div class="typo-lh-header" style="\n            display: grid;\n            grid-template-columns: 220px 80px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 0 16px 8px;\n            border-bottom: 2px solid var(--color-stroke-frame);\n            margin-bottom: 4px;\n          ">\n            <span style="${LABEL_HEADER}">Token</span>\n            <span style="${LABEL_HEADER}">Valor</span>\n            <span style="${LABEL_HEADER}">Exemplo</span>\n          </div>\n\n          \x3c!-- line-height 1 ───────────────────────────────────────────── --\x3e\n          <div class="typo-lh-row" style="\n            display: grid;\n            grid-template-columns: 220px 80px 1fr;\n            gap: 8px 20px;\n            align-items: start;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-line-height-xs\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">1</span>\n            <p style="\n              margin: 0;\n              font-size: var(--size-font-body-14, 14px);\n              line-height: 1;\n              color: var(--color-text-essential-body);\n            ">Os tokens de tipografia garantem hierarquia visual e legibilidade consistente em toda a interface do Venus.ds.</p>\n          </div>\n\n          \x3c!-- line-height 1.1 ─────────────────────────────────────────── --\x3e\n          <div class="typo-lh-row" style="\n            display: grid;\n            grid-template-columns: 220px 80px 1fr;\n            gap: 8px 20px;\n            align-items: start;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-line-height-sm\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">1.1</span>\n            <p style="\n              margin: 0;\n              font-size: var(--size-font-body-14, 14px);\n              line-height: 1.1;\n              color: var(--color-text-essential-body);\n            ">Os tokens de tipografia garantem hierarquia visual e legibilidade consistente em toda a interface do Venus.ds.</p>\n          </div>\n\n          \x3c!-- line-height 1.25 ────────────────────────────────────────── --\x3e\n          <div class="typo-lh-row" style="\n            display: grid;\n            grid-template-columns: 220px 80px 1fr;\n            gap: 8px 20px;\n            align-items: start;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-line-height-md\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">1.25</span>\n            <p style="\n              margin: 0;\n              font-size: var(--size-font-body-14, 14px);\n              line-height: 1.25;\n              color: var(--color-text-essential-body);\n            ">Os tokens de tipografia garantem hierarquia visual e legibilidade consistente em toda a interface do Venus.ds.</p>\n          </div>\n\n          \x3c!-- line-height 1.5 ─────────────────────────────────────────── --\x3e\n          <div class="typo-lh-row" style="\n            display: grid;\n            grid-template-columns: 220px 80px 1fr;\n            gap: 8px 20px;\n            align-items: start;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-line-height-lg\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">1.5</span>\n            <p style="\n              margin: 0;\n              font-size: var(--size-font-body-14, 14px);\n              line-height: 1.5;\n              color: var(--color-text-essential-body);\n            ">Os tokens de tipografia garantem hierarquia visual e legibilidade consistente em toda a interface do Venus.ds.</p>\n          </div>\n\n          \x3c!-- line-height 1.7 ─────────────────────────────────────────── --\x3e\n          <div class="typo-lh-row" style="\n            display: grid;\n            grid-template-columns: 220px 80px 1fr;\n            gap: 8px 20px;\n            align-items: start;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-line-height-xl\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">1.7</span>\n            <p style="\n              margin: 0;\n              font-size: var(--size-font-body-14, 14px);\n              line-height: 1.7;\n              color: var(--color-text-essential-body);\n            ">Os tokens de tipografia garantem hierarquia visual e legibilidade consistente em toda a interface do Venus.ds.</p>\n          </div>\n\n          \x3c!-- line-height 2 ───────────────────────────────────────────── --\x3e\n          <div class="typo-lh-row" style="\n            display: grid;\n            grid-template-columns: 220px 80px 1fr;\n            gap: 8px 20px;\n            align-items: start;\n            padding: 14px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-line-height-2xl\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n            <span style="font-size: 13px; color: var(--color-text-essential-body);">2</span>\n            <p style="\n              margin: 0;\n              font-size: var(--size-font-body-14, 14px);\n              line-height: 2;\n              color: var(--color-text-essential-body);\n            ">Os tokens de tipografia garantem hierarquia visual e legibilidade consistente em toda a interface do Venus.ds.</p>\n          </div>\n        </section>\n\n        \x3c!-- ══ FAMÍLIAS TIPOGRÁFICAS ════════════════════════════════════ --\x3e\n        <section style="margin-bottom: 56px;">\n          <h2 style="\n            font-size: clamp(16px, 2vw, 18px);\n            font-weight: 700;\n            color: var(--color-text-essential-heading);\n            margin: 0 0 8px;\n          ">Famílias Tipográficas</h2>\n          <p style="margin: 0 0 24px; color: var(--color-text-essential-caption); font-size: 13px;">\n            Famílias de fonte disponíveis no Venus.ds.\n          </p>\n\n          \x3c!-- Cabeçalho --\x3e\n          <div class="typo-family-header" style="\n            display: grid;\n            grid-template-columns: 160px 240px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 0 16px 8px;\n            border-bottom: 2px solid var(--color-stroke-frame);\n            margin-bottom: 4px;\n          ">\n            <span style="${LABEL_HEADER}">Família</span>\n            <span style="${LABEL_HEADER}">Token CSS</span>\n            <span style="${LABEL_HEADER}">Preview</span>\n          </div>\n\n          \x3c!-- DM Sans ────────────────────────────────────────────────── --\x3e\n          <div class="typo-family-row" style="\n            display: grid;\n            grid-template-columns: 160px 240px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 16px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              DM Sans\n            </span>\n            <code style="${CODIGO_INLINE}">--font-family-primary</code>\n            <span style="\n              font-family: var(--font-family-primary, \'DM Sans\', sans-serif);\n              font-size: var(--size-font-heading-20, 20px);\n              color: var(--color-text-essential-heading);\n            ">ABCDEFGHIJ abcdefghij 0123456789</span>\n          </div>\n\n          \x3c!-- Source Code Pro ─────────────────────────────────────────── --\x3e\n          <div class="typo-family-row" style="\n            display: grid;\n            grid-template-columns: 160px 240px 1fr;\n            gap: 8px 20px;\n            align-items: center;\n            padding: 16px 16px;\n            border-bottom: 1px solid var(--color-stroke-frame);\n          ">\n            <span style="font-size: 13px; font-weight: 600; color: var(--color-text-essential-body);">\n              Source Code Pro\n            </span>\n            <span style="font-size: 12px; color: var(--color-text-essential-caption);">\n              --tds-ref-font-family-code\n              <span style="${BADGE_DEFINIR}">a definir</span>\n            </span>\n            <span style="\n              font-family: \'Source Code Pro\', monospace;\n              font-size: var(--size-font-body-14, 14px);\n              color: var(--color-text-essential-heading);\n            ">ABCDEFGHIJ abcdefghij 0123456789</span>\n          </div>\n        </section>\n\n        \x3c!-- ══ NOTA SOBRE TOKENS A DEFINIR ════════════════════════════ --\x3e\n        <aside style="\n          margin-top: 48px;\n          padding: 16px 20px;\n          background: var(--color-theme-upper);\n          border-left: var(--size-stoke-2, 2px) solid var(--color-state-feedback-warning-surface-base);\n          border-radius: 0 var(--size-radius-4, 4px) var(--size-radius-4, 4px) 0;\n        ">\n          <p style="margin: 0 0 6px; font-weight: 600; color: var(--color-text-essential-heading);">\n            Tokens sinalizados como "a definir"\n          </p>\n          <p style="margin: 0; font-size: 13px; color: var(--color-text-essential-caption);">\n            Os tokens\n            <code style="${CODIGO_INLINE}">--lui-typography-*</code>,\n            <code style="${CODIGO_INLINE}">--tds-ref-font-weight-*</code>,\n            <code style="${CODIGO_INLINE}">--tds-ref-font-line-height-*</code> e\n            <code style="${CODIGO_INLINE}">--tds-ref-font-family-code</code>\n            ainda não foram definidos no pacote de tokens do Venus.ds.\n            Enquanto isso, utilize os tokens globais disponíveis\n            (<code style="${CODIGO_INLINE}">--size-font-*</code>,\n            <code style="${CODIGO_INLINE}">--font-family-primary</code>) e\n            alinhe com o time de tokens a criação dos aliases definitivos.\n            Os pesos sinalizados como "não disponível" correspondem a variações da DM Sans\n            não carregadas no Storybook (somente 400, 500 e 700 estão disponíveis).\n          </p>\n        </aside>\n\n      </div>\n    `,\n    styles: [`\n        @media (max-width: 1024px) {\n          .typo-page { max-width: 100% !important; }\n        }\n        @media (max-width: 640px) {\n          .typo-scale-header,\n          .typo-size-header,\n          .typo-weight-header,\n          .typo-lh-header,\n          .typo-family-header { display: none !important; }\n          .typo-scale-row {\n            grid-template-columns: 100px 1fr !important;\n            gap: 4px 12px !important;\n            padding: 10px 12px !important;\n          }\n          .typo-size-row {\n            grid-template-columns: 56px 1fr !important;\n            gap: 4px 12px !important;\n            padding: 10px 12px !important;\n          }\n          .typo-weight-row {\n            grid-template-columns: 80px 1fr !important;\n            gap: 4px 12px !important;\n            padding: 10px 12px !important;\n          }\n          .typo-lh-row {\n            grid-template-columns: 1fr !important;\n            gap: 4px !important;\n            padding: 10px 12px !important;\n          }\n          .typo-family-row {\n            grid-template-columns: 1fr !important;\n            gap: 4px !important;\n            padding: 10px 12px !important;\n          }\n        }\n      `]\n  })\n}',...Documentacao.parameters?.docs?.source}}},__webpack_require__.d(__webpack_exports__,["Documentacao",0,Documentacao,"__namedExportsOrder",0,["Documentacao"],"default",0,__WEBPACK_DEFAULT_EXPORT__])}}]);
